/**
 * Extensions to the Raphael.js library used by draw2d
 * 
 * These extensions provide additional functionality for working with
 * SVG elements and graphical operations in draw2d.
 */
export class RaphaelExt {
  /**
   * Applies all Raphael extensions
   * This method is typically called once during draw2d initialization
   */
  static apply(): void;
}